clc; clearvars;

root_dir = "C:\Users\tely1\PhD";

addpath(genpath(fullfile(root_dir, "O3_Lidar\")));

% DIAL Processing Functions
% addpath(genpath(fullfile(root_dir, "O3_Lidar\proc_functions")));

% Signal Analysis and Modeling Functions
addpath(genpath(fullfile(root_dir, "signal_analysis\")));
%%
start_day       = datetime(datetime("2024-10-01", "InputFormat", "uuuu-MM-dd"), "InputFormat", "uuuu-MM-dd"); %[control:datePicker:8a9f]{"position":[28,79]}
end_day         = datetime(datetime("2024-10-31", "InputFormat", "uuuu-MM-dd"), "InputFormat", "uuuu-MM-dd"); %[control:datePicker:4f06]{"position":[28,79]}
data_path       = fullfile(root_dir, "lidar_data");
result_path     = fullfile(root_dir, "O3_processed_data");
log_path        = fullfile(root_dir, "O3_processed_data");

log_file        = fullfile(log_path, "o3_process.log");

if ~exist(result_path, "dir")
    mkdir(result_path)
end

if ~exist(log_path, "dir")
    mkdir(log_path)
end

if ~exist(log_file, "file")
    fid = fopen(log_file, "a");
    if fid ~= -1
        fclose(fid);
    end
end

folders = dir(data_path);
folders = folders([folders.isdir]);

for i = 1:size(folders, 1) %[output:group:5d039cb0]
    tmp_folder = folders(i).name;

    try
        folderDate = datetime(tmp_folder, "InputFormat", "uuuuMMdd", "Format", "uuuuMMdd");
    catch
        continue
    end

    if folderDate >= start_day && folderDate <= end_day
        fprintf("processing %s\n", tmp_folder); %[output:21123c24]
        output_filename = sprintf("o3_processed_%04d%02d%02d.mat", year(folderDate), month(folderDate), day(folderDate));

        try
            out = process(fullfile(data_path, tmp_folder), fullfile(result_path, output_filename));
        catch ME
            warning("Processing failed for %s: %s", tmp_folder, ME.message);

            fid = fopen(log_file, "a");
            if fid ~= -1
                fprintf(fid, "%s | %s | %s | %s\n", ...
                    char(datetime("now", "Format", "yyyy-MM-dd HH:mm:ss")), ...
                    tmp_folder, ...
                    "FAILED", ...
                    ME.message);
                fclose(fid);
            end
        end
    end
end %[output:group:5d039cb0]
%%
plt = "mg"; %[control:dropdown:11a3]{"position":[7,11]}
switch plt
    case "an"
        q_nr_plt = out.q_o3_an_nr;
        q_fr_plt = out.q_o3_an_fr;
        q_merge_plt = out.q_o3_an_merged;
    case "pc"
        q_nr_plt = out.q_o3_pc_nr;
        q_fr_plt = out.q_o3_pc_fr;
        q_merge_plt = out.q_o3_pc_merged;
    case "mg"
        q_nr_plt = out.q_o3_mg_nr;
        q_fr_plt = out.q_o3_mg_fr;
        q_merge_plt = out.q_o3_mg_merged;
end

times_avg = out.times_avg;
z_km_vec = out.z_vec.*1e-3;

ND_plot(times_avg,z_km_vec,q_nr_plt,[0 120],[0 3],"Ozone Mixing Ratio NR","Altitude (km)", "ppb", "",12) %[output:5b816424]
ND_plot(times_avg,z_km_vec,q_fr_plt,[0 120],[0 10],"Ozone Mixing Ratio FR","Altitude (km)", "ppb", "",12) %[output:322ee585]
ND_plot(times_avg,z_km_vec,q_merge_plt,[0 120],[0 10],"Ozone Mixing Ratio FR-NR Merge","Altitude (km)", "ppb", "",12) %[output:85da23d0]
%%\ Uncertainty profiles
n_profiles = length(out.times_avg);
profile_id = 5; %[control:slider:a903]{"position":[14,15]}
uncertainty_range = "merged"; %[control:dropdown:a904]{"position":[21,29]}

profile_id = max(1,min(round(profile_id),n_profiles));
z_km_vec = out.z_vec(:).*1e-3;

switch uncertainty_range
    case "nr"
        u_plt = out.pc_uncertainty_nr;
        u_total_plt = out.uNO3_nr(:,profile_id);
        N_plt = out.N_o3_nr_pc(:,profile_id);
    case "fr"
        u_plt = out.pc_uncertainty_fr;
        u_total_plt = out.uNO3_fr(:,profile_id);
        N_plt = out.N_o3_fr_pc(:,profile_id);
    case "merged"
        u_plt = out.pc_uncertainty_merged;
        u_total_plt = out.uNO3_pc_merged(:,profile_id);
        N_plt = out.N_o3_pc_merged(:,profile_id);
end

% Plot component magnitudes on logarithmic axes; this is the PC subtotal.
% ? is it necessary to use the magnitude. need to understand negative values
u_profiles = abs([u_plt.DET(:,profile_id) u_plt.SAT(:,profile_id) u_plt.BKG(:,profile_id) u_plt.O3(:,profile_id) u_plt.RAYLEIGH(:,profile_id) u_total_plt]);
% u_profiles = [u_plt.DET(:,profile_id) u_plt.SAT(:,profile_id) u_plt.BKG(:,profile_id) u_plt.O3(:,profile_id) u_plt.RAYLEIGH(:,profile_id) u_total_plt];
u_profiles(u_profiles <= 0) = NaN;

u_relative = u_profiles ./ abs(N_plt) .* 100;
u_relative(N_plt <= 0,:) = NaN;
u_mixing = u_profiles ./ out.Na(:,profile_id) .* 1e9;

figure; %[output:12a5b350]
set(gcf,"Position",[100 100 1000 650]); %[output:12a5b350]

subplot(1,2,1) %[output:12a5b350]
h = semilogx(u_relative,z_km_vec,"LineWidth",1.2); %[output:12a5b350]
h(6).LineStyle = "--"; %[output:12a5b350]
xlim([0.01 300]); %[output:12a5b350]
ylim([0 10]); %[output:12a5b350]
xlabel("Ozone Number Density Uncertainty (%)"); %[output:12a5b350]
ylabel("Altitude (km)"); %[output:12a5b350]
legend("Detection","Saturation","Background","Ozone cross section","Rayleigh extinction","PC subtotal","Location","best","FontSize",10); %[output:12a5b350]
grid on; %[output:12a5b350]

subplot(1,2,2) %[output:12a5b350]
h = semilogx(u_mixing,z_km_vec,"LineWidth",1.2); %[output:12a5b350]
h(6).LineStyle = "--"; %[output:12a5b350]
xlim([0.01 100]); %[output:12a5b350]
ylim([0 10]); %[output:12a5b350]
xlabel("Ozone Mixing Ratio Uncertainty (ppb)"); %[output:12a5b350]
ylabel("Altitude (km)"); %[output:12a5b350]
legend("Detection","Saturation","Background","Ozone cross section","Rayleigh extinction","PC subtotal","Location","best","FontSize",10); %[output:12a5b350]
grid on; %[output:12a5b350]

sgtitle(sprintf("PC %s Uncertainty | Profile %d | %s",upper(uncertainty_range),profile_id,string(out.times_avg(profile_id)))); %[output:12a5b350]

